1	/**
2	 * Foam banks along the stream (refs 03–10) + whirlpool rim foam.
3	 *  - berm: ONE continuous lumpy lather bank per side, swept along the course (custom shader:
4	 *    two-scale cellular soap bubbles with derivative bump lighting, lavender crevices, pores,
5	 *    faint iridescent rim). This is what makes the banks read as continuous foam, not cotton balls.
6	 *  - puffs: instanced bubble puffs sitting ON the berm crest (silhouette lumps), in ~40-unit chunks
7	 *    so only chunks near Benny are drawn; quality 'low' halves density and uses 20-tri puffs.
8	 *  - foam rings on the whirlpool rim and along its spiral bands (rotating with the swirl)
9	 */
10	import * as THREE from 'three';
11	import { type Course, WORLD, funnelY } from '../world/course';
12	import { EDGE_LIFT } from './waterRibbon';
13	import { SPIRAL_C, FUNNEL_LIFT } from './whirlpool';
14	import { FRAG_FX_GLSL, FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
15	
16	interface Puff { p: THREE.Vector3; r: number; c: number }
17	
18	// ---------------------------------------------------------------------------------- berm profile
19	/** berm spans e ∈ [BERM_IN, BERM_OUT] units outward from the ribbon edge (negative = over the water) */
20	export const BERM_IN = -0.6;
21	export const BERM_OUT = 1.2;
22	const hash1 = (n: number) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
23	const noise1 = (x: number) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return hash1(i) * (1 - u) + hash1(i + 1) * u; };
24	/** 0..1 lumpiness of the bank at (s, side) — CPU only, baked into the mesh and the puff placement */
25	export function bermLump(s: number, side: number): number {
26	  return 0.55 * noise1(s * 0.33 + side * 31.7) + 0.45 * noise1(s * 1.05 + side * 7.3);
27	}
28	/** CPU cellular "bubble dome" field (0..1) so the bank silhouette is a pile of round lumps */
29	export function bermDomes(s: number, e: number, side: number): number {
30	  const gs = s / 0.95, ge = e / 0.62 + side * 11.3;
31	  const i0 = Math.floor(gs), j0 = Math.floor(ge);
32	  let best = 0;
33	  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
34	    const i = i0 + di, j = j0 + dj;
35	    const ox = hash1(i * 17.13 + j * 3.71), oy = hash1(i * 5.31 + j * 19.7 + 4.2);
36	    const r = 0.45 + 0.4 * hash1(i * 7.7 + j * 13.1 + 9.9);
37	    const dx = (i + ox - gs) / r, dy = (j + oy - ge) / r;
38	    best = Math.max(best, 1 - (dx * dx + dy * dy));
39	  }
40	  return Math.max(0, best);
41	}
42	
43	/** height (along course up) of the bank surface at e units outward from the edge */
44	export function bermHeight(e: number, hw: number, lump: number): number {
45	  const uIn = Math.max(0, (hw + BERM_IN) / hw);
46	  const hIn = EDGE_LIFT * uIn * uIn * uIn - 0.07;
47	  const ep = 0.08 + 0.22 * lump;
48	  const hp = EDGE_LIFT + 0.14 + 0.5 * lump;
49	  const hOut = -0.95;
50	  if (e <= ep) {
51	    const t = Math.min(1, Math.max(0, (e - BERM_IN) / (ep - BERM_IN)));
52	    return hIn + (hp - hIn) * (1 - (1 - t) * (1 - t));
53	  }
54	  const t = Math.min(1, (e - ep) / (BERM_OUT - ep));
55	  return hp + (hOut - hp) * t * t;
56	}
57	
58	/** full bank surface height incl. bubble domes (shared by the mesh and the puff placement) */
59	export function bermSurface(s: number, e: number, side: number, hw: number): number {
60	  const domeK = Math.min(1, Math.max(0, (e + 0.3) / 0.35)) * Math.min(1, Math.max(0, (BERM_OUT - 0.1 - e) / 0.4));
61	  return bermHeight(e, hw, bermLump(s, side)) + 0.2 * domeK * Math.sqrt(bermDomes(s, e, side));
62	}
63	
64	const BERM_VERT = /* glsl */ `
65	attribute vec3 aFoam;    // x = e (units outward from the stream edge), y = s, z = side (-1 / 1)
66	uniform float uTime;
67	varying vec3 vFoam;
68	varying vec3 vPosW;
69	varying vec3 vNormalW;
70	#include <fog_pars_vertex>
71	void main() {
72	  // gentle breathing of the lather (never at the water line)
73	  float k = smoothstep(-0.2, 0.3, aFoam.x);
74	  vec3 p = position + normal * (0.03 * k * sin(uTime * 1.6 + aFoam.y * 2.1 + aFoam.z * 3.0));
75	  vec4 wp = modelMatrix * vec4(p, 1.0);
76	  vPosW = wp.xyz;
77	  vNormalW = normalize(mat3(modelMatrix) * normal);
78	  vFoam = aFoam;
79	  vec4 mvPosition = viewMatrix * wp;
80	  gl_Position = projectionMatrix * mvPosition;
81	  #include <fog_vertex>
82	}
83	`;
84	
85	const BERM_FRAG = /* glsl */ `
86	uniform float uTime;
87	uniform vec2 uOutro;     // amount, chamber start s
88	uniform vec3 uLightDir;
89	varying vec3 vFoam;
90	varying vec3 vPosW;
91	varying vec3 vNormalW;
92	#include <fog_pars_fragment>
93	${NOISE_GLSL}
94	${FRAG_FX_GLSL}
95	void main() {
96	  float s = vFoam.y;
97	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
98	    float n = vnoise(vec2(vFoam.x * 3.0, s * 0.35)) * 0.7 + 0.3;
99	    if (n < uOutro.x * 1.15) discard;
100	  }
101	  vec2 p = vec2(vFoam.x * vFoam.z * 1.1, s - uTime * 0.25);
102	  // detail fade with distance (cells per pixel)
103	  float fw = max(fwidth(p.x), fwidth(p.y));
104	  float k1 = 1.0 - smoothstep(0.12, 0.3, fw * 1.6);
105	  float k2 = 1.0 - smoothstep(0.12, 0.3, fw * 3.8);
106	  float c1 = mix(0.45, cells(p * 1.6), k1);
107	  #ifdef LOW_Q
108	  float c2 = c1;
109	  #else
110	  float c2 = mix(0.45, cells(p * 3.8 + 11.0), k2);
111	  #endif
112	  // bubble domes: bright cell centres, deep crevices between bubbles
113	  float bub = (1.0 - c1 * c1) * 0.6 + (1.0 - c2 * c2) * 0.4;
114	  vec3 N0 = normalize(vNormalW);
115	  if (!gl_FrontFacing) N0 = -N0;
116	  #ifdef LOW_Q
117	  vec3 N = N0;
118	  #else
119	  vec3 N = bumpNormal(vPosW, N0, bub * 0.1);
120	  #endif
121	  vec3 L = normalize(uLightDir);
122	  vec3 V = normalize(cameraPosition - vPosW);
123	  float diff = 0.55 + 0.45 * max(dot(N, L), 0.0);
124	  vec3 white = vec3(1.0, 1.0, 1.0);
125	  vec3 lav = vec3(0.7, 0.68, 0.98);
126	  vec3 col = mix(lav, white, 0.3 + 0.7 * clamp(N.y * 0.5 + 0.5, 0.0, 1.0)) * diff;
127	  col = mix(col, lav * 0.8, smoothstep(0.6, 0.95, c1) * 0.7 * k1);
128	  col = mix(col, lav * 0.9, smoothstep(0.65, 0.95, c2) * 0.4 * k2);
129	  // tiny pores (open bubbles)
130	  #ifndef LOW_Q
131	  vec2 pp = p * 7.0 + 5.0;
132	  float pc = cells(pp);
133	  float kp = 1.0 - smoothstep(0.1, 0.25, fw * 7.0);
134	  col = mix(col, vec3(0.58, 0.56, 0.88), (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.75 * kp);
135	  #endif
136	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 28.0);
137	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);
138	  col += vec3(1.0) * spec * 0.45 + iridescent(fres * 1.4 + c1 * 0.6) * fres * 0.18;
139	  gl_FragColor = vec4(col * 0.96, 1.0);
140	  ${FRAG_TAIL}
141	}
142	`;
143	
144	function rng(seed: number) {
145	  let a = seed >>> 0;
146	  return () => {
147	    a = (a + 0x6d2b79f5) >>> 0;
148	    let t = a;
149	    t = Math.imul(t ^ (t >>> 15), t | 1);
150	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
151	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
152	  };
153	}
154	
155	const FOAM_COLORS = ['#ffffff', '#f4f6ff', '#eef0ff', '#ffffff', '#eaf6ff'].map((c) => new THREE.Color(c));
156	
157	function makeMaterial() {
158	  const m = new THREE.MeshStandardMaterial({
159	    color: '#ffffff',
160	    roughness: 0.4,
161	    metalness: 0.0,
162	    emissive: new THREE.Color('#eef0ff'),
163	    emissiveIntensity: 0.45,
164	    envMapIntensity: 1.0,
165	  });
166	  // subtle soap-film rim tint
167	  m.onBeforeCompile = (sh) => {
168	    sh.fragmentShader = sh.fragmentShader.replace(
169	      '#include <emissivemap_fragment>',
170	      `#include <emissivemap_fragment>
171	       float rimF = pow(1.0 - clamp(dot(normalize(vNormal), normalize(vViewPosition)), 0.0, 1.0), 2.5);
172	       totalEmissiveRadiance += vec3(0.55, 0.35, 0.75) * rimF * 0.35;`,
173	    );
174	  };
175	  return m;
176	}
177	
178	export interface FoamSystem {
179	  group: THREE.Group;
180	  whirlGroup: THREE.Group;
181	  berm: THREE.Mesh;
182	  update(time: number, focusS: number, outro?: number): void;
183	  instanceCount: number;
184	}
185	
186	/** continuous lather bank along both stream edges (skips the 03 whirlpool interior) */
187	function createBerm(course: Course, s0: number, s1: number, skip: [number, number], quality: 'high' | 'low') {
188	  const ds = quality === 'high' ? 0.32 : 0.8;
189	  const E = quality === 'high' ? [BERM_IN, -0.4, -0.25, -0.1, 0.04, 0.18, 0.34, 0.52, 0.75, 0.98, BERM_OUT] : [BERM_IN, -0.2, 0.15, 0.55, BERM_OUT];
190	  const rows = Math.ceil((s1 - s0) / ds) + 1;
191	  const C = E.length;
192	  const n = rows * C * 2;
193	  const pos = new Float32Array(n * 3);
194	  const foam = new Float32Array(n * 3);
195	  const tmp = new THREE.Vector3();
196	  let k = 0;
197	  const rowS: number[] = [];
198	  for (let i = 0; i < rows; i++) {
199	    const s = Math.min(s1, s0 + i * ds);
200	    rowS.push(s);
201	    const f = course.sample(s);
202	    const hw = course.widthAt(s) / 2;
203	    for (const side of [-1, 1]) {
204	      for (let j = 0; j < C; j++) {
205	        // left side is mirrored so every row runs inner → outer; bubble domes everywhere except
206	        // at the water line (keeps the lace edge flush with the stream)
207	        const e = E[j];
208	        const h = bermSurface(s, e, side, hw);
209	        tmp.copy(f.pos).addScaledVector(f.right, side * (hw + e)).addScaledVector(f.up, h);
210	        tmp.toArray(pos, k * 3);
211	        foam[k * 3] = e;
212	        foam[k * 3 + 1] = s;
213	        foam[k * 3 + 2] = side;
214	        k++;
215	      }
216	    }
217	  }
218	  const idx: number[] = [];
219	  const rowStride = C * 2;
220	  for (let i = 0; i < rows - 1; i++) {
221	    const sa = rowS[i], sb = rowS[i + 1];
222	    if (sb > skip[0] && sa < skip[1]) continue;
223	    for (let sideI = 0; sideI < 2; sideI++) {
224	      for (let j = 0; j < C - 1; j++) {
225	        const a = i * rowStride + sideI * C + j, b = a + 1, c = a + rowStride, d = c + 1;
226	        // CCW seen from above on both sides (side +1 runs +right, side −1 runs −right)
227	        if (sideI === 1) idx.push(a, b, c, b, d, c);
228	        else idx.push(a, c, b, b, c, d);
229	      }
230	    }
231	  }
232	  const geo = new THREE.BufferGeometry();
233	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
234	  geo.setAttribute('aFoam', new THREE.BufferAttribute(foam, 3));
235	  geo.setIndex(idx);
236	  geo.computeVertexNormals();
237	  const uniforms = withFog({
238	    uTime: { value: 0 },
239	    uOutro: { value: new THREE.Vector2(0, course.stage('08').s0) },
240	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
241	  });
242	  const mat = new THREE.ShaderMaterial({
243	    uniforms,
244	    vertexShader: BERM_VERT,
245	    fragmentShader: BERM_FRAG,
246	    fog: true,
247	    side: THREE.DoubleSide,
248	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
249	  });
250	  const mesh = new THREE.Mesh(geo, mat);
251	  mesh.name = 'foam_berm';
252	  mesh.frustumCulled = false;
253	  return { mesh, uniforms };
254	}
255	
256	export function createFoam(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): FoamSystem {
257	  const { s0, s1, quality } = opts;
258	  const rand = rng(1337);
259	  const density = quality === 'high' ? 1 : 0.5;
260	  const geo = new THREE.IcosahedronGeometry(1, quality === 'high' ? 1 : 0);
261	  const mat = makeMaterial();
262	  const group = new THREE.Group();
263	  group.name = 'foam_banks';
264	  const st03 = course.stage('03'), st04 = course.stage('04');
265	  const chunkLen = 40;
266	  const chunks: { mesh: THREE.InstancedMesh; sa: number; sb: number }[] = [];
267	  let total = 0;
268	  const tmpM = new THREE.Matrix4();
269	  const tmpQ = new THREE.Quaternion();
270	  const tmpS = new THREE.Vector3();
271	
272	  const build = (list: Puff[], parent: THREE.Object3D, sa: number, sb: number) => {
273	    if (!list.length) return;
274	    const mesh = new THREE.InstancedMesh(geo, mat, list.length);
275	    list.forEach((pf, i) => {
276	      tmpQ.setFromEuler(new THREE.Euler(rand() * 6, rand() * 6, rand() * 6));
277	      tmpS.set(pf.r, pf.r * (0.75 + rand() * 0.25), pf.r);
278	      tmpM.compose(pf.p, tmpQ, tmpS);
279	      mesh.setMatrixAt(i, tmpM);
280	      mesh.setColorAt(i, FOAM_COLORS[pf.c % FOAM_COLORS.length]);
281	    });
282	    mesh.instanceMatrix.needsUpdate = true;
283	    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
284	    mesh.computeBoundingSphere();
285	    parent.add(mesh);
286	    chunks.push({ mesh, sa, sb });
287	    total += list.length;
288	  };
289	
290	  // ---- continuous lather bank (berm) along both edges ----
291	  const skip: [number, number] = [st03.s0 + 4, st04.s0 - 6];
292	  const berm = createBerm(course, s0, s1, skip, quality);
293	  group.add(berm.mesh);
294	
295	  // ---- bubble puffs sitting on the bank crest (silhouette lumps) ----
296	  for (let sa = s0; sa < s1; sa += chunkLen) {
297	    const sb = Math.min(s1, sa + chunkLen);
298	    const list: Puff[] = [];
299	    // skip most of 03 (the whirlpool has its own foam), keep the chute→rim hand-over
300	    for (let s = sa; s < sb; s += 0.5 / density) {
301	      if (s > skip[0] && s < skip[1]) continue;
302	      const f = course.sample(s);
303	      const hw = course.widthAt(s) / 2;
304	      for (const side of [-1, 1]) {
305	        if (rand() < 0.2) continue;
306	        const e = -0.22 + rand() * 0.7;
307	        const r = 0.09 + rand() * 0.17;
308	        const p = f.pos.clone().addScaledVector(f.right, side * (hw + e)).addScaledVector(f.up, bermSurface(s, e, side, hw) + r * 0.05);
309	        list.push({ p, r, c: (rand() * 5) | 0 });
310	      }
311	      // bigger lather lumps on the crest
312	      if (rand() < 0.1 * density) {
313	        const side = rand() < 0.5 ? -1 : 1;
314	        const n = 4 + ((rand() * 7) | 0);
315	        const ec = 0.05 + rand() * 0.45;
316	        for (let k = 0; k < n; k++) {
317	          const ss = Math.min(s1, Math.max(s0, s + (rand() - 0.5) * 2.4));
318	          if (ss > skip[0] && ss < skip[1]) continue;
319	          const f2 = course.sample(ss);
320	          const hw2 = course.widthAt(ss) / 2;
321	          const e = ec + (rand() - 0.5) * 0.6;
322	          const r = 0.17 + rand() * 0.25;
323	          const h = bermSurface(ss, e, side, hw2) + r * (0.1 + rand() * 0.35);
324	          const p = f2.pos.clone().addScaledVector(f2.right, side * (hw2 + e)).addScaledVector(f2.up, h);
325	          list.push({ p, r, c: (rand() * 5) | 0 });
326	        }
327	      }
328	    }
329	    build(list, group, sa - 6, sb + 6);
330	  }
331	
332	  // ---- whirlpool: rim ring + spiral band foam (rotates with the swirl) ----
333	  const whirlGroup = new THREE.Group();
334	  whirlGroup.name = 'foam_whirlpool';
335	  const b = WORLD.basin;
336	  whirlGroup.position.set(b.center.x, 0, b.center.z);
337	  const wl: Puff[] = [];
338	  // rim: cloud clusters of soap foam with a thin continuous fringe between them
339	  const nClusters = Math.round(26 * density);
340	  for (let k = 0; k < nClusters; k++) {
341	    const th0 = rand() * Math.PI * 2;
342	    const n = 10 + ((rand() * 16) | 0);
343	    for (let i = 0; i < n; i++) {
344	      const th = th0 + (rand() - 0.5) * 0.35;
345	      const r = b.rimRadius - 0.7 + (rand() - 0.4) * 1.3;
346	      const sz = 0.18 + rand() * 0.42;
347	      wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.35 + rand() * 0.55, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
348	    }
349	  }
350	  const nRim = Math.round(200 * density);
351	  for (let i = 0; i < nRim; i++) {
352	    const th = rand() * Math.PI * 2;
353	    const r = b.rimRadius - 0.4 + (rand() - 0.5) * 0.6;
354	    const sz = 0.1 + rand() * 0.18;
355	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
356	  }
357	  // along 3 spiral flow lines (constant th - C ln r) to echo the white foam bands
358	  const nBand = Math.round(60 * density);
359	  for (let i = 0; i < nBand; i++) {
360	    const band = ((i % 3) * Math.PI * 2) / 3 + 0.4;
361	    const r = 3.0 + rand() * (b.rimRadius - 3.6);
362	    const th = band + SPIRAL_C * Math.log(r) + (rand() - 0.5) * 0.12;
363	    const sz = 0.07 + rand() * 0.13;
364	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
365	  }
366	  const whirlStart = chunks.length;
367	  build(wl, whirlGroup, st03.s0 - 30, st04.s0 + 25);
368	  group.add(whirlGroup);
369	
370	  return {
371	    group,
372	    whirlGroup,
373	    berm: berm.mesh,
374	    instanceCount: total,
375	    update(time, focusS, outro = 0) {
376	      berm.uniforms.uTime.value = time;
377	      (berm.uniforms.uOutro.value as THREE.Vector2).x = outro;
378	      const s08 = course.stage('08').s0;
379	      for (let i = 0; i < chunks.length; i++) {
380	        const c = chunks[i];
381	        c.mesh.visible = c.sb > focusS - 25 && c.sa < focusS + 140 && !(outro > 0.3 && c.sb > s08 + 8);
382	      }
383	      // rotate whirlpool foam about the basin axis with the swirl (θ decreasing = course direction)
384	      whirlGroup.rotation.y = -time * 0.45 * ((Math.PI * 2) / 3);
385	      void whirlStart;
386	    },
387	  };
388	}
389

1	/**
2	 * Rider splash crown: a thin animated water sheet that flares out of the surface around Benny's
3	 * waterline (ref 05: white splash/wake fanning out to both sides and backwards).
4	 *
5	 * One small mesh (polar grid: angle × radial), shaped and animated entirely in the vertex shader,
6	 * and drawn with a translucent "finger + lace" fragment shader. It is placed every frame at the
7	 * computed water surface under Benny (index.ts `wake()`), so it always sits exactly on the stream
8	 * that carries him. Hidden automatically when wake() stops being called (intro / outro).
9	 */
10	import * as THREE from 'three';
11	import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
12	
13	const VERT = /* glsl */ `
14	attribute vec2 aPolar;   // x = angle (0 = straight behind Benny, ±pi = in front), y = radial 0..1
15	uniform float uTime;
16	uniform float uR;        // waterline radius of Benny's body (units)
17	uniform float uStrength; // 0..1
18	varying vec2 vPolar;
19	varying float vSide;
20	varying vec3 vPosW;
21	#include <fog_pars_vertex>
22	float h1(float n) { return fract(sin(n) * 43758.5453); }
23	float n1(float x) { float i = floor(x); float f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f); }
24	void main() {
25	  float th = aPolar.x;
26	  float t = aPolar.y;
27	  float ath = abs(th);
28	  // strongest beside Benny and diagonally behind him, low bow wave in front, calm right behind
29	  float side = smoothstep(0.55, 1.1, ath) * (1.0 - 0.85 * smoothstep(1.8, 2.5, ath));
30	  float wob = n1(th * 4.0 + uTime * 5.0) * 0.5 + n1(th * 9.0 - uTime * 7.0) * 0.5;
31	  float reach = mix(1.0, 1.8 + 0.45 * wob, t) * (0.8 + 0.2 * side);
32	  float r = uR * mix(0.92, reach, t);
33	  // sheet rises steeply out of the water at the body, then arcs back down (crown profile)
34	  float lift = uR * (0.55 + 0.25 * wob) * side * uStrength;
35	  float y = lift * sin(3.14159 * pow(t, 0.7)) * (1.0 - 0.35 * t) - 0.04 * uR;
36	  vec3 p = vec3(sin(th) * r, y, cos(th) * r);   // local: x = side, y = up, z = backwards
37	  vec4 wp = modelMatrix * vec4(p, 1.0);
38	  vPosW = wp.xyz;
39	  vPolar = aPolar;
40	  vSide = side;
41	  vec4 mvPosition = viewMatrix * wp;
42	  gl_Position = projectionMatrix * mvPosition;
43	  #include <fog_vertex>
44	}
45	`;
46	
47	const FRAG = /* glsl */ `
48	uniform float uTime;
49	uniform float uStrength;
50	varying vec2 vPolar;
51	varying float vSide;
52	varying vec3 vPosW;
53	#include <fog_pars_fragment>
54	${NOISE_GLSL}
55	void main() {
56	  float th = vPolar.x;
57	  float t = vPolar.y;
58	  // thin radial fingers streaming outward, laced by a fine soap-foam network
59	  float fing = vnoise(vec2(th * 26.0, t * 1.2 - uTime * 4.0));
60	  fing = smoothstep(0.52, 0.8, fing);
61	  float net = smoothstep(0.3, 0.46, cells(vec2(th * 14.0, t * 7.0 - uTime * 3.0)));
62	  float body = 1.0 - smoothstep(0.06, 0.22, t);          // churned rim right at the body
63	  float a = max(body * (0.35 + 0.65 * net), fing * (0.45 + 0.55 * net));
64	  a *= (1.0 - smoothstep(0.5, 0.92, t)) * vSide * uStrength;
65	  if (a < 0.02) discard;
66	  vec3 V = normalize(cameraPosition - vPosW);
67	  vec3 col = mix(vec3(0.62, 0.92, 1.0), vec3(1.15, 1.18, 1.2), smoothstep(0.2, 0.75, a));
68	  gl_FragColor = vec4(col, clamp(a * 0.95, 0.0, 0.95));
69	  ${FRAG_TAIL}
70	}
71	`;
