73	export interface RiderSplash {
74	  mesh: THREE.Mesh;
75	  uniforms: Record<string, THREE.IUniform>;
76	  /** place on the water under Benny: waterline centre + frame + body radius at the waterline */
77	  place(center: THREE.Vector3, forward: THREE.Vector3, up: THREE.Vector3, radius: number, strength: number): void;
78	  update(time: number, dt: number): void;
79	}
80	
81	export function createRiderSplash(quality: 'high' | 'low'): RiderSplash {
82	  const S = quality === 'high' ? 56 : 28;
83	  const R = quality === 'high' ? 7 : 4;
84	  const polar = new Float32Array((S + 1) * (R + 1) * 2);
85	  let k = 0;
86	  for (let i = 0; i <= S; i++) {
87	    for (let j = 0; j <= R; j++) {
88	      polar[k++] = -Math.PI + (2 * Math.PI * i) / S;
89	      polar[k++] = j / R;
90	    }
91	  }
92	  const idx: number[] = [];
93	  for (let i = 0; i < S; i++) {
94	    for (let j = 0; j < R; j++) {
95	      const a = i * (R + 1) + j, b = a + 1, c = a + R + 1, d = c + 1;
96	      idx.push(a, c, b, b, c, d);
97	    }
98	  }
99	  const geo = new THREE.BufferGeometry();
100	  geo.setAttribute('aPolar', new THREE.BufferAttribute(polar, 2));
101	  // dummy position attribute (positions are generated in the vertex shader)
102	  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array((S + 1) * (R + 1) * 3), 3));
103	  geo.setIndex(idx);
104	  const uniforms = withFog({ uTime: { value: 0 }, uR: { value: 0.7 }, uStrength: { value: 0 } });
105	  const mat = new THREE.ShaderMaterial({
106	    uniforms,
107	    vertexShader: VERT,
108	    fragmentShader: FRAG,
109	    fog: true,
110	    transparent: true,
111	    depthWrite: false,
112	    side: THREE.DoubleSide,
113	  });
114	  const mesh = new THREE.Mesh(geo, mat);
115	  mesh.name = 'rider_splash';
116	  mesh.frustumCulled = false;
117	  mesh.renderOrder = 3;
118	  mesh.visible = false;
119	  const basis = new THREE.Matrix4();
120	  const back = new THREE.Vector3();
121	  const side = new THREE.Vector3();
122	  let target = 0;
123	  let fed = false;
124	  return {
125	    mesh,
126	    uniforms,
127	    place(center, forward, up, radius, strength) {
128	      back.copy(forward).multiplyScalar(-1);
129	      side.crossVectors(up, back).normalize(); // x × y = z  →  (side, up, back) right-handed
130	      basis.makeBasis(side, up, back);
131	      mesh.quaternion.setFromRotationMatrix(basis);
132	      mesh.position.copy(center);
133	      uniforms.uR.value = radius;
134	      target = strength;
135	      fed = true;
136	    },
137	    update(time, dt) {
138	      uniforms.uTime.value = time;
139	      if (!fed) target = 0;
140	      fed = false;
141	      const s = uniforms.uStrength.value as number;
142	      const v = dt > 0 ? s + (target - s) * Math.min(1, dt * 6) : target;
143	      uniforms.uStrength.value = v;
144	      mesh.visible = v > 0.01;
145	    },
146	  };
147	}
