1	/**
2	 * Iridescent soap bubbles.
3	 *  - big bubbles: InstancedMesh spheres with a thin-film shader (rainbow Fresnel rim, white
4	 *    window highlight, nearly clear centre) — pooled around Benny (focusS) or the Drum A volume
5	 *  - small bubbles: one THREE.Points draw of hundreds of tiny ring-sprite bubbles hugging the water
6	 * Bubbles drift with the flow, rise, wobble, and are respawned ahead when left behind.
7	 */
8	import * as THREE from 'three';
9	import { type Course, WORLD } from '../world/course';
10	import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
11	
12	const BIG_VERT = /* glsl */ `
13	attribute float aSeed;
14	varying vec3 vPosW;
15	varying vec3 vNormalW;
16	varying float vSeed;
17	#include <fog_pars_vertex>
18	void main() {
19	  vec4 wp = modelMatrix * instanceMatrix * vec4(position, 1.0);
20	  vPosW = wp.xyz;
21	  vNormalW = normalize(mat3(modelMatrix) * mat3(instanceMatrix) * normal);
22	  vSeed = aSeed;
23	  vec4 mvPosition = viewMatrix * wp;
24	  gl_Position = projectionMatrix * mvPosition;
25	  #include <fog_vertex>
26	}
27	`;
28	const BIG_FRAG = /* glsl */ `
29	uniform float uTime;
30	uniform vec3 uLightDir;
31	varying vec3 vPosW;
32	varying vec3 vNormalW;
33	varying float vSeed;
34	#include <fog_pars_fragment>
35	${NOISE_GLSL}
36	void main() {
37	  vec3 N = normalize(vNormalW);
38	  vec3 V = normalize(cameraPosition - vPosW);
39	  float nv = clamp(dot(N, V), 0.0, 1.0);
40	  float f = 1.0 - nv;
41	  // swirling thin-film thickness
42	  float swirl = vnoise(N.xy * 2.5 + vec2(uTime * 0.3 + vSeed * 10.0, vSeed * 5.0));
43	  vec3 irid = iridescent(f * 1.6 + swirl * 0.8 + vSeed);
44	  float rim = pow(f, 2.0);
45	  vec3 col = mix(vec3(0.85, 0.9, 1.0), irid, 0.9) * (0.3 + rim * 1.8);
46	  // window-like specular highlights
47	  vec3 R = reflect(-V, N);
48	  float spec = pow(clamp(dot(R, normalize(uLightDir)), 0.0, 1.0), 90.0);
49	  float spec2 = pow(clamp(dot(R, normalize(vec3(-0.6, 0.2, 0.7))), 0.0, 1.0), 40.0) * 0.5;
50	  col += vec3(1.0) * (spec * 2.4 + spec2);
51	  float alpha = clamp(0.06 + rim * 0.85 + spec * 0.9 + spec2 * 0.5, 0.0, 0.95);
52	  gl_FragColor = vec4(col, alpha);
53	  ${FRAG_TAIL}
54	}
55	`;
56	
57	const PT_VERT = /* glsl */ `
58	attribute float aSize;
59	attribute float aSeed;
60	uniform float uScale;
61	varying float vSeed;
62	varying float vPx;
63	#include <fog_pars_vertex>
64	void main() {
65	  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
66	  gl_PointSize = clamp(aSize * uScale / -mvPosition.z, 1.0, 64.0);
67	  vPx = gl_PointSize;
68	  vSeed = aSeed;
69	  gl_Position = projectionMatrix * mvPosition;
70	  #include <fog_vertex>
71	}
72	`;
73	const PT_FRAG = /* glsl */ `
74	uniform float uTime;
75	varying float vSeed;
76	varying float vPx;
77	#include <fog_pars_fragment>
78	${NOISE_GLSL}
79	void main() {
80	  vec2 c = gl_PointCoord - 0.5;
81	  float d = length(c) * 2.0;
82	  if (d > 1.0) discard;
83	  float ring = smoothstep(0.55, 0.85, d) * (1.0 - smoothstep(0.88, 1.0, d));
84	  vec3 irid = iridescent(d * 0.8 + vSeed + atan(c.y, c.x) * 0.1);
85	  float hl = smoothstep(0.28, 0.0, length(c - vec2(-0.17, -0.17)));
86	  vec3 col = mix(vec3(1.0), irid, 0.55) * ring * 1.3 + vec3(1.0) * hl * 1.5;
87	  // tiny sprites must not read as solid white dots: fade them, keep only rim + glint when large
88	  float alpha = clamp(ring * 0.85 + hl + 0.04, 0.0, 1.0) * (0.25 + 0.75 * smoothstep(3.0, 10.0, vPx));
89	  gl_FragColor = vec4(col, alpha);
90	  ${FRAG_TAIL}
91	}
92	`;
93	
94	interface BubbleState {
95	  s: number;
96	  pos: THREE.Vector3;
97	  vel: THREE.Vector3;
98	  size: number;
99	  phase: number;
100	  age: number;
101	  life: number;
102	}
103	
104	export interface BubbleSystem {
105	  group: THREE.Group;
106	  big: THREE.InstancedMesh;
107	  small: THREE.Points;
108	  update(time: number, dt: number, focusS: number, camera: THREE.Camera, density?: number): void;
109	  counts: { big: number; small: number };
110	}
111	
112	function rnd(a: number, b: number) {
113	  return a + Math.random() * (b - a);
114	}
115	
116	export function createBubbles(course: Course, opts: { quality: 'high' | 'low'; sStart: number }): BubbleSystem {
117	  const quality = opts.quality;
118	  const nBig = quality === 'high' ? 44 : 22;
119	  const nSmall = quality === 'high' ? 360 : 160;
120	  const group = new THREE.Group();
121	  group.name = 'bubbles';
122	  const dA = WORLD.drumA;
123	  const drumEnd = course.marks['02_drain'] ?? course.stage('03').s0;
124	
125	  // ---- big ----
126	  const sphere = new THREE.SphereGeometry(1, quality === 'high' ? 24 : 14, quality === 'high' ? 16 : 10);
127	  const seeds = new Float32Array(nBig).map(() => Math.random());
128	  sphere.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seeds, 1));
129	  const bigUniforms = withFog({ uTime: { value: 0 }, uLightDir: { value: new THREE.Vector3(0.4, 0.9, 0.5).normalize() } });
130	  const big = new THREE.InstancedMesh(
131	    sphere,
132	    new THREE.ShaderMaterial({ uniforms: bigUniforms, vertexShader: BIG_VERT, fragmentShader: BIG_FRAG, fog: true, transparent: true, depthWrite: false }),
133	    nBig,
134	  );
135	  big.name = 'bubbles_big';
136	  big.frustumCulled = false;
137	  big.renderOrder = 5;
138	  group.add(big);
139	
140	  // ---- small ----
141	  const sPos = new Float32Array(nSmall * 3);
142	  const sSize = new Float32Array(nSmall);
143	  const sSeed = new Float32Array(nSmall).map(() => Math.random());
144	  const pGeo = new THREE.BufferGeometry();
145	  pGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3).setUsage(THREE.DynamicDrawUsage));
146	  pGeo.setAttribute('aSize', new THREE.BufferAttribute(sSize, 1));
147	  pGeo.setAttribute('aSeed', new THREE.BufferAttribute(sSeed, 1));
148	  const ptUniforms = withFog({ uTime: { value: 0 }, uScale: { value: 600 } });
149	  const small = new THREE.Points(
150	    pGeo,
151	    new THREE.ShaderMaterial({ uniforms: ptUniforms, vertexShader: PT_VERT, fragmentShader: PT_FRAG, fog: true, transparent: true, depthWrite: false }),
152	  );
153	  small.name = 'bubbles_small';
154	  small.frustumCulled = false;
155	  small.renderOrder = 4;
156	  group.add(small);
157	
158	  const bigS: BubbleState[] = Array.from({ length: nBig }, () => ({ s: 0, pos: new THREE.Vector3(), vel: new THREE.Vector3(), size: 1, phase: 0, age: 0, life: 1 }));
159	  const smallS: BubbleState[] = Array.from({ length: nSmall }, () => ({ s: 0, pos: new THREE.Vector3(), vel: new THREE.Vector3(), size: 1, phase: 0, age: 0, life: 1 }));
160	
161	  const tmp = new THREE.Vector3();
162	  const spawn = (b: BubbleState, focusS: number, isBig: boolean, initial: boolean) => {
163	    b.phase = Math.random() * 6.28;
164	    b.age = 0;
165	    b.life = rnd(6, 14);
166	    if (focusS < drumEnd) {
167	      // Drum A volume: big bubbles floating around the drum, small ones near the water
168	      const th = rnd(0, Math.PI * 2);
169	      const r = Math.sqrt(Math.random()) * (dA.radius - 0.9);
170	      const x = dA.center.x + Math.cos(th) * r;
171	      const y = isBig ? rnd(dA.waterY - 0.2, dA.center.y + dA.radius * 0.7) : rnd(dA.waterY + 0.05, dA.waterY + 1.6);
172	      const z = rnd(dA.zBack + 0.6, dA.zDoor - 0.4);
173	      b.pos.set(x, y, z);
174	      b.s = focusS;
175	      b.vel.set(rnd(-0.15, 0.15), rnd(0.05, 0.25), rnd(-0.1, 0.1));
176	      b.size = isBig ? (Math.random() < 0.25 ? rnd(0.45, 0.85) : rnd(0.16, 0.42)) : rnd(0.05, 0.16);
177	      return;
178	    }
179	    const ahead = isBig ? rnd(initial ? -2 : 18, 75) : rnd(initial ? -3 : 8, 45);
180	    let s = Math.max(opts.sStart, focusS + ahead);
181	    if (s > course.length - 0.5) s = course.length - rnd(0.5, 30); // near the route end: fill the chamber behind
182	    const f = course.sample(s);
183	    const hw = course.widthAt(s) / 2;
184	    const tube = course.prop(s, 'tube');
185	    let lat: number, h: number;
186	    if (isBig) {
187	      // mostly low over the stream and its foam banks (refs 05–07), a few drifting higher
188	      const latMax = tube > 0 ? Math.min(tube * 0.8, hw + 2.2) : hw + 6;
189	      lat = rnd(-latMax, latMax);
190	      h = tube > 0 ? (Math.random() < 0.75 ? rnd(0.5, 3.2) : rnd(3.2, tube * 1.1)) : rnd(0.3, 7);
191	      b.size = Math.random() < 0.2 ? rnd(0.45, 0.8) : rnd(0.14, 0.4);
192	    } else {
193	      lat = tube > 0 ? rnd(-hw - 1.2, hw + 1.2) : rnd(-hw - 4, hw + 4);
194	      h = rnd(0.15, 2.6) * (Math.random() < 0.7 ? 0.5 : 1.2);
195	      b.size = rnd(0.05, 0.17);
196	    }
197	    b.pos.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, h);
198	    b.s = s;
199	    const flow = course.prop(s, 'speed') * (isBig ? 0.12 : 0.25);
200	    b.vel.copy(f.tan).multiplyScalar(flow).addScaledVector(f.up, rnd(0.05, 0.3));
201	  };
202	
203	  let lastFocus = -1e9;
204	  const tmpM = new THREE.Matrix4();
205	  const one = new THREE.Quaternion();
206	  const scl = new THREE.Vector3();
207	  const camPos = new THREE.Vector3();
208	
209	  return {
210	    group,
211	    big,
212	    small,
213	    counts: { big: nBig, small: nSmall },
214	    update(time, dt, focusS, camera, density = 1) {
215	      bigUniforms.uTime.value = time;
216	      ptUniforms.uTime.value = time;
217	      const jump = Math.abs(focusS - lastFocus) > 25;
218	      const crossedDrum = (lastFocus < drumEnd) !== (focusS < drumEnd);
219	      if (jump || crossedDrum) {
220	        for (const b of bigS) spawn(b, focusS, true, true);
221	        for (const b of smallS) spawn(b, focusS, false, true);
222	      }
223	      lastFocus = focusS;
224	      camera.getWorldPosition(camPos);
225	      // pixel scale for point sprites
226	      const persp = camera as THREE.PerspectiveCamera;
227	      const vh = (typeof window !== 'undefined' ? window.innerHeight : 800) * (typeof window !== 'undefined' ? Math.min(2, window.devicePixelRatio || 1) : 1);
228	      ptUniforms.uScale.value = persp.isPerspectiveCamera ? vh / (2 * Math.tan(THREE.MathUtils.degToRad(persp.fov) / 2)) : 600;
229	      const inDrum = focusS < drumEnd;
230	      const step = (b: BubbleState, isBig: boolean) => {
231	        b.age += dt;
232	        b.pos.addScaledVector(b.vel, dt);
233	        tmp.set(Math.sin(time * 1.3 + b.phase), Math.cos(time * 1.1 + b.phase * 1.7), Math.sin(time * 0.9 + b.phase * 0.6)).multiplyScalar(0.12 * dt);
234	        b.pos.add(tmp);
235	        // near the route end (outro) keep bubbles anywhere in the last ~30 units
236	        const behind = !inDrum && b.s < Math.min(focusS, course.length - 32) - (isBig ? 6 : 4);
237	        if (behind || b.age > b.life) spawn(b, focusS, isBig, false);
238	      };
239	      const bigLimit = Math.round((inDrum ? Math.min(nBig, 16) : nBig) * density);
240	      const smallLimit = Math.round((inDrum ? nSmall * 0.45 : nSmall) * density);
241	      for (let i = 0; i < nBig; i++) {
242	        const b = bigS[i];
243	        step(b, true);
244	        const pop = i < bigLimit ? Math.min(1, b.age * 2, (b.life - b.age) * 2) : 0;
245	        const sz = b.size * Math.max(0.001, pop) * (1 + 0.04 * Math.sin(time * 4 + b.phase));
246	        scl.set(sz, sz, sz);
247	        tmpM.compose(b.pos, one, scl);
248	        big.setMatrixAt(i, tmpM);
249	      }
250	      big.instanceMatrix.needsUpdate = true;
251	      for (let i = 0; i < nSmall; i++) {
252	        const b = smallS[i];
253	        step(b, false);
254	        b.pos.toArray(sPos, i * 3);
255	        sSize[i] = i < smallLimit ? b.size * Math.min(1, b.age * 3, (b.life - b.age) * 3) : 0;
256	      }
257	      (pGeo.attributes.position as THREE.BufferAttribute).needsUpdate = true;
258	      (pGeo.attributes.aSize as THREE.BufferAttribute).needsUpdate = true;
259	    },
260	  };
261	}
