1	/**
2	 * Spray droplets: one pooled THREE.Points draw for Benny's wake fans, landing splashes, the
3	 * final-wave crest spray and spout splashes. Simple ballistic CPU sim (gravity along -Y).
4	 */
5	import * as THREE from 'three';
6	import { FRAG_TAIL, withFog } from './glsl';
7	
8	const VERT = /* glsl */ `
9	attribute float aSize;
10	attribute float aAlpha;
11	uniform float uScale;
12	varying float vAlpha;
13	#include <fog_pars_vertex>
14	void main() {
15	  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
16	  gl_PointSize = clamp(aSize * uScale / -mvPosition.z, 1.0, 48.0);
17	  vAlpha = aAlpha;
18	  gl_Position = projectionMatrix * mvPosition;
19	  #include <fog_vertex>
20	}
21	`;
22	const FRAG = /* glsl */ `
23	varying float vAlpha;
24	#include <fog_pars_fragment>
25	void main() {
26	  vec2 c = gl_PointCoord - 0.5;
27	  float d = length(c) * 2.0;
28	  if (d > 1.0) discard;
29	  float body = 1.0 - smoothstep(0.6, 1.0, d);
30	  float hl = smoothstep(0.35, 0.0, length(c - vec2(-0.15, -0.15)));
31	  vec3 col = mix(vec3(0.75, 0.95, 1.0), vec3(1.0), 0.5 + 0.5 * hl) * 1.25;
32	  gl_FragColor = vec4(col, body * vAlpha * 0.9);
33	  ${FRAG_TAIL}
34	}
35	`;
36	
37	export interface Spray {
38	  points: THREE.Points;
39	  emit(pos: THREE.Vector3, vel: THREE.Vector3, size: number, life: number): void;
40	  update(dt: number, camera: THREE.Camera): void;
41	  capacity: number;
42	}
43	
44	export function createSpray(quality: 'high' | 'low'): Spray {
45	  const N = quality === 'high' ? 600 : 220;
46	  const pos = new Float32Array(N * 3);
47	  const vel = new Float32Array(N * 3);
48	  const size = new Float32Array(N);
49	  const alpha = new Float32Array(N);
50	  const age = new Float32Array(N).fill(1e9);
51	  const life = new Float32Array(N).fill(1);
52	  const geo = new THREE.BufferGeometry();
53	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3).setUsage(THREE.DynamicDrawUsage));
54	  geo.setAttribute('aSize', new THREE.BufferAttribute(size, 1).setUsage(THREE.DynamicDrawUsage));
55	  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1).setUsage(THREE.DynamicDrawUsage));
56	  const uniforms = withFog({ uScale: { value: 600 } });
57	  const points = new THREE.Points(geo, new THREE.ShaderMaterial({ uniforms, vertexShader: VERT, fragmentShader: FRAG, fog: true, transparent: true, depthWrite: false }));
58	  points.name = 'spray';
59	  points.frustumCulled = false;
60	  points.renderOrder = 6;
61	  let cursor = 0;
62	  return {
63	    points,
64	    capacity: N,
65	    emit(p, v, s, l) {
66	      const i = cursor;
67	      cursor = (cursor + 1) % N;
68	      p.toArray(pos, i * 3);
69	      v.toArray(vel, i * 3);
70	      size[i] = s;
71	      age[i] = 0;
72	      life[i] = l;
73	    },
74	    update(dt, camera) {
75	      const persp = camera as THREE.PerspectiveCamera;
76	      const vh = (typeof window !== 'undefined' ? window.innerHeight : 800) * (typeof window !== 'undefined' ? Math.min(2, window.devicePixelRatio || 1) : 1);
77	      uniforms.uScale.value = persp.isPerspectiveCamera ? vh / (2 * Math.tan(THREE.MathUtils.degToRad(persp.fov) / 2)) : 600;
78	      for (let i = 0; i < N; i++) {
79	        if (age[i] > life[i]) { alpha[i] = 0; continue; }
80	        age[i] += dt;
81	        vel[i * 3 + 1] -= 18 * dt;
82	        pos[i * 3] += vel[i * 3] * dt;
