61	export function createWater(course: Course, opts: { quality?: 'high' | 'low' } = {}): WaterSystem {
62	  const quality = opts.quality ?? 'high';
63	  const group = new THREE.Group();
64	  group.name = 'water_system';
65	
66	  const drainMark = course.marks['02_drain'] ?? course.stage('02').s1 - 2;
67	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08'), st09 = course.stage('09');
68	  const ribbonS0 = drainMark - 1;
69	  const ribbon = createRibbon(course, { s0: ribbonS0, s1: course.length, quality });
70	  // open the funnel where the 04 slide tube leaves the basin (the course exits the spiral at
71	  // r≈2.8, just outside the drain hole, and the slide then runs beneath the funnel surface)
72	  const cutPts: THREE.Vector3[] = [];
73	  for (let i = 0; i < 8; i++) {
74	    const s = st04.s0 - 3 + (i / 7) * 34;
75	    const f = course.sample(s);
76	    cutPts.push(f.pos.clone().addScaledVector(f.up, 1.2));
77	  }
78	  const whirl = createWhirlpool(quality, { points: cutPts, radius: Math.max(3.6, course.stage('04').tube * 0.85) });
79	  const drum = createDrumWater(quality);
80	  const wave = createFinalWave(course, quality);
81	  const puddles = createPuddles();
82	  const foam = createFoam(course, { s0: ribbonS0, s1: course.length, quality });
83	  const bubbles = createBubbles(course, { quality, sStart: ribbonS0 });
84	  const spray = createSpray(quality);
85	  const crown = createRiderSplash(quality);
86	  group.add(ribbon.mesh, whirl.mesh, drum.group, wave.mesh, puddles.group, foam.group, bubbles.group, spray.points, crown.mesh);
87	
88	  const parts: Record<string, THREE.Object3D> = { ribbon: ribbon.mesh, whirlpool: whirl.mesh, drum: drum.group, drumSwirl: drum.swirl, finalWave: wave.mesh, puddles: puddles.group, foam: foam.group, foamBerm: foam.berm, bubbles: bubbles.group, bubblesSmall: bubbles.small, bubblesBig: bubbles.big, spray: spray.points, splashCrown: crown.mesh };
89	  const controls: WaterControls = { drumSwirl: 0, drumAgitation: 0, outro: 0 };
90	  // QA: ?waterhide=crown,spray,bubbles,foam,foamBerm,ribbon … hides water parts (isolation captures)
91	  const qaHide = typeof location !== 'undefined' ? (new URLSearchParams(location.search).get('waterhide') ?? '').split(',').filter(Boolean) : [];
92	  let focus = 0;
93	  let curTime = 0;
94	  const tmpV = new THREE.Vector3();
95	  const tmpV2 = new THREE.Vector3();
96	  const tmpV3 = new THREE.Vector3();
97	  const rnd = (a: number, b: number) => a + Math.random() * (b - a);
98	
99	  /** 0 = ribbon fully shown, 1 = whirlpool surface takes over (mirrors the ribbon vertex shader) */
100	  const whirlBlend = (s: number) => smooth(st03.s0 + 0.5, st03.s0 + 3.5, s) * (1 - smooth(st04.s0 - 9, st04.s0 - 1.5, s));
101	
102	  const surfaceHeight = (s: number, lateral: number, t: number): number => {
103	    if (s < ribbonS0) {
104	      // Drum A: absolute swell height relative to the course point
105	      const p = course.pointAt(s, lateral, 0, tmpV);
106	      const up = course.sample(s).up;
107	      return (drum.heightAt(p.x, p.z, t) - p.y) / Math.max(0.3, up.y);
108	    }
109	    const hr = ribbon.heightAt(s, lateral, t);
110	    const k = whirlBlend(s);
111	    if (k <= 0) return hr;
112	    const f = course.sample(s);
113	    const p = tmpV.copy(f.pos).addScaledVector(f.right, lateral);
114	    const b = WORLD.basin;
115	    const r = Math.hypot(p.x - b.center.x, p.z - b.center.z);
116	    const yW = funnelY(r) + FUNNEL_LIFT + whirlpoolHeight(p.x, p.z, t);
117	    const hw = (yW - p.y) / Math.max(0.3, f.up.y);
118	    return hr * (1 - k) + hw * k;
119	  };
120	
121	  return {
122	    group,
123	    controls,
124	    parts,
125	    surfaceHeight,
126	    stats: () => ({ instances: foam.instanceCount, bubbles: bubbles.counts.big, smallBubbles: bubbles.counts.small, sprayCapacity: spray.capacity }),
127	    update(time, dt, focusS, camera) {
128	      focus = focusS;
129	      curTime = time;
130	      ribbon.uniforms.uTime.value = time;
131	      whirl.uniforms.uTime.value = time;
132	      drum.uniforms.uTime.value = time;
133	      drum.uniforms.uAgitation.value = controls.drumAgitation;
134	      drum.swirlUniforms.uSwirl.value = controls.drumSwirl;
135	      drum.swirl.visible = controls.drumSwirl > 0.001;
136	      wave.uniforms.uTime.value = time;
137	      puddles.uniforms.uTime.value = time;
138	      puddles.uniforms.uAmount.value = controls.outro;
139	      (ribbon.uniforms.uOutro.value as THREE.Vector2).x = controls.outro;
140	      puddles.group.visible = controls.outro > 0.001;
141	      // region visibility (perf): only what the camera around focusS can see
142	      drum.group.visible = focusS < st03.s0 + 12;
143	      whirl.mesh.visible = focusS > drainMark - 8 && focusS < st04.s0 + 45;
144	      wave.mesh.visible = focusS > st08.s0 - 25;
145	      // when Benny is off the ribbon (drum / whirlpool), no ribbon wake
146	      if (focusS < ribbonS0 || whirlBlend(focusS) > 0.5) (ribbon.uniforms.uBenny.value as THREE.Vector3).z = 0;
147	      foam.update(time, focusS, controls.outro);
148	      bubbles.update(time, dt, focusS, camera, 1 - 0.7 * controls.outro);
149	      // crest spray off the final wave
150	      if (wave.mesh.visible && focusS > st09.s0 - 20 && focusS < st09.s1 + 20 && controls.outro < 0.5) {
151	        const n = quality === 'high' ? 3 : 1;
152	        for (let i = 0; i < n; i++) {
153	          const c = wave.crest[(Math.random() * wave.crest.length) | 0];
154	          if (!c) break;
155	          const f = course.sample(Math.min(course.length, Math.max(0, focusS)));
156	          tmpV2.copy(f.right).multiplyScalar(rnd(1, 3.5)).addScaledVector(f.up, rnd(1.5, 4)).addScaledVector(f.tan, rnd(-1, 2));
157	          spray.emit(c, tmpV2, rnd(0.08, 0.2), rnd(0.5, 1.0));
158	        }
159	      }
160	      spray.update(dt, camera);
161	      crown.update(time, dt);
162	      for (const k of qaHide) { const o = parts[k]; if (o) o.visible = false; }
163	    },
164	    wake(pos, forward, right, speed, dt) {
165	      // Benny's arc length / lateral from his actual position (focus lags one frame)
166	      const f0 = course.sample(Math.max(0, focus));
167	      const d = tmpV3.copy(pos).sub(f0.pos);
168	      const s = Math.min(course.length, Math.max(0, focus + d.dot(f0.tan)));
169	      const f = course.sample(s);
170	      d.copy(pos).sub(f.pos);
171	      const lateral = d.dot(f.right);
172	      // body radius from the ride offset (centre = surface + BENNY_RIDE_OFFSET · radius)
173	      const above = d.dot(f.up) - surfaceHeight(s, lateral, curTime);
174	      const bodyR = THREE.MathUtils.clamp(above / BENNY_RIDE_OFFSET, 0.4, 2.0);
175	      const waterlineR = bodyR * Math.sqrt(1 - BENNY_RIDE_OFFSET * BENNY_RIDE_OFFSET);
176	      const strength = Math.min(1, speed / 8);
177	      if (s >= ribbonS0 && whirlBlend(s) < 0.5) {
178	        (ribbon.uniforms.uBenny.value as THREE.Vector3).set(s, lateral, strength);
179	        ribbon.uniforms.uBennyR.value = waterlineR;
180	      }
181	      // 3D splash crown flaring out of the surface at the waterline
182	      const center = tmpV.copy(pos).addScaledVector(f.up, -above);
183	      crown.place(center, forward, f.up, waterlineR, strength);
184	      // side fans of droplets (refs 05/07/08/10)
185	      const rate = speed * (quality === 'high' ? 6 : 2);
186	      const n = Math.floor(rate * dt + Math.random());
187	      const up = tmpV2.crossVectors(right, forward).normalize();
188	      for (let i = 0; i < n; i++) {
189	        const side = Math.random() < 0.5 ? -1 : 1;
190	        const p = center.clone().addScaledVector(right, side * waterlineR * rnd(1.0, 1.5)).addScaledVector(forward, rnd(-0.5, 0.2)).addScaledVector(up, rnd(0.0, 0.2));
191	        const v = right.clone().multiplyScalar(side * rnd(1.2, 3.4)).addScaledVector(up, rnd(1.8, 4.2)).addScaledVector(forward, rnd(-2.0, 0.5));
192	        spray.emit(p, v, rnd(0.05, 0.13), rnd(0.35, 0.7));
193	      }
194	    },
195	    splash(pos, up, strength) {
196	      const n = Math.round(30 * strength * (quality === 'high' ? 1 : 0.5));
197	      for (let i = 0; i < n; i++) {
198	        const dir = new THREE.Vector3(rnd(-1, 1), 0, rnd(-1, 1)).normalize().multiplyScalar(rnd(1, 4) * strength);
199	        dir.addScaledVector(up, rnd(3, 7) * strength);
200	        spray.emit(pos, dir, rnd(0.08, 0.22), rnd(0.5, 1.1));
201	      }
202	    },
203	  };
204	}
