52	export function createBennyRuntime(
53	  scene: THREE.Object3D,
54	  clips: THREE.AnimationClip[],
55	  opts: { furQuality?: 'high' | 'low' } = {},
56	): BennyRuntime {
57	  const root = new THREE.Group();
58	  root.name = 'Benny';
59	  root.add(scene);
60	
61	  // ---- fur upgrade ----
62	  const furs: FurHandle[] = [];
63	  const toReplace: THREE.Mesh[] = [];
64	  scene.traverse((o) => {
65	    const m = o as THREE.Mesh;
66	    if (m.isMesh && m.name.startsWith('fur_') && m.userData?.fur) toReplace.push(m);
67	  });
68	  for (const m of toReplace) {
69	    const p = { ...(m.userData.fur as FurParams) };
70	    if (opts.furQuality === 'low') p.shells = Math.max(6, Math.round(p.shells * 0.6));
71	    const h = makeFur(m, p);
72	    m.parent!.add(h.mesh);
73	    m.parent!.remove(m);
74	    furs.push(h);
75	  }
76	
77	  const get = (n: string) => scene.getObjectByName(n)!;
78	  const body = get('body');
79	  const pom = get('pom');
80	  const eyeL = get('eyeL');
81	  const eyeR = get('eyeR');
82	  const eyesGroup = get('eyes');
83	  const pomRest = pom.quaternion.clone();
84	
85	  // ---- animation mixer: idle ↔ swim blend, tumble / peek on demand ----
86	  const mixer = new THREE.AnimationMixer(scene);
87	  const act = (name: string) => {
88	    const c = clips.find((k) => k.name === name);
89	    return c ? mixer.clipAction(c) : null;
90	  };
91	  const aIdle = act('idle'), aSwim = act('swim'), aTumble = act('tumble'), aPeek = act('peek');
92	  for (const a of [aIdle, aSwim, aTumble, aPeek]) a?.play();
93	  const setW = (a: THREE.AnimationAction | null, w: number) => a && a.setEffectiveWeight(w);
94	
95	  let expression: 'happy' | 'dizzy' | 'peek' = 'happy';
96	  const setExpression = (e: 'happy' | 'dizzy' | 'peek') => {
97	    expression = e;
98	    for (const s of ['L', 'R']) {
99	      const h = scene.getObjectByName(`eye${s}_happy`);
100	      const d = scene.getObjectByName(`eye${s}_dizzy`);
101	      if (h) h.visible = e !== 'dizzy';
102	      if (d) d.visible = e === 'dizzy';
103	    }
104	    for (const k of ['happy', 'dizzy', 'peek']) {
105	      const m = scene.getObjectByName(`mouth_${k}`);
106	      if (m) m.visible = k === e;
107	    }
108	    eyesGroup.scale.setScalar(e === 'peek' ? 1.06 : 1);
109	  };
110	  setExpression('happy');
111	
112	  // ---- secondary motion state ----
113	  let pomAngX = 0, pomVelX = 0, pomAngZ = 0, pomVelZ = 0;
114	  let lastY = 0, lastVy = 0;
115	  let blinkT = 1.7;
116	  let lean = 0;
117	  let lift = 0;
118	  const liftMax = rideLift();
119	  const tmp = new THREE.Vector3();
120	  const qLean = new THREE.Quaternion();
121	  const qPom = new THREE.Quaternion();
122	  const eAxis = new THREE.Euler();
123	
124	  const update: BennyRuntime['update'] = (dt, st) => {
125	    dt = Math.min(dt, 1 / 20);
126	    // clip weights
127	    const tumble = !!st.tumble;
128	    const swim = tumble ? 0 : THREE.MathUtils.clamp(st.swim, 0, 1);
129	    const peek = expression === 'peek' && !tumble ? 1 : 0;
130	    setW(aTumble, tumble ? 1 : 0);
131	    setW(aPeek, peek);
132	    setW(aSwim, peek ? 0 : swim);
133	    setW(aIdle, tumble || peek ? 0 : 1 - swim);
134	    if (aSwim) aSwim.timeScale = 0.8 + Math.min(1.2, st.speed / 14);
135	    mixer.update(dt);
136	
137	    // ride height (see BENNY_RIDE_LIFT): eased so mode switches never pop
138	    const liftTarget = tumble || peek ? 0 : liftMax * THREE.MathUtils.smoothstep(swim, 0.5, 0.9);
139	    lift += (liftTarget - lift) * (1 - Math.exp(-dt * 7));
140	    scene.position.y = lift;
141	
142	    // steering lean (roll) + slight yaw into the turn
143	    lean += (THREE.MathUtils.clamp(st.steer, -1, 1) * 0.28 - lean) * Math.min(1, dt * 6);
144	    qLean.setFromEuler(eAxis.set(0, -lean * 0.6, -lean));
145	    body.quaternion.multiply(qLean);
146	
147	    // pom-pom spring: driven by vertical acceleration, steering and speed jitter
148	    root.getWorldPosition(tmp);
149	    const vy = (tmp.y - lastY) / Math.max(dt, 1e-3);
150	    const ay = THREE.MathUtils.clamp((vy - lastVy) / Math.max(dt, 1e-3), -80, 80);
151	    lastY = tmp.y; lastVy = vy;
