function loadScene(): Promise<THREE.Group> {
  if (!cached) cached = new GLTFLoader().loadAsync(BENNY_URL).then((g) => {
    const s = g.scene as THREE.Group;
    s.userData.animations = g.animations;
    return s;
  });
  return cached;
}

