359	  const berm = createBerm(course, s0, s1, skip, quality);
360	  group.add(berm.mesh);
361	
362	  // ---- bubble puffs sitting on the bank crest (silhouette lumps) ----
363	  for (let sa = s0; sa < s1; sa += chunkLen) {
364	    const sb = Math.min(s1, sa + chunkLen);
365	    const list: Puff[] = [];
366	    // skip most of 03 (the whirlpool has its own foam), keep the chute→rim hand-over
367	    for (let s = sa; s < sb; s += 0.5 / density) {
368	      if (s > skip[0] && s < skip[1]) continue;
