378	      // bigger lather lumps on the crest
379	      if (rand() < 0.1 * density) {
380	        const side = rand() < 0.5 ? -1 : 1;
381	        const n = 4 + ((rand() * 7) | 0);
382	        const ec = 0.05 + rand() * 0.45;
383	        for (let k = 0; k < n; k++) {
384	          const ss = Math.min(s1, Math.max(s0, s + (rand() - 0.5) * 2.4));
385	          if (ss > skip[0] && ss < skip[1]) continue;
386	          const f2 = course.sample(ss);
387	          const hw2 = course.widthAt(ss) / 2;
388	          const e = ec + (rand() - 0.5) * 0.6;
389	          const r = 0.17 + rand() * 0.25;
390	          const h = bermSurface(ss, e, side, hw2) + r * (0.1 + rand() * 0.35);
391	          const p = f2.pos.clone().addScaledVector(f2.right, side * (hw2 + e)).addScaledVector(f2.up, h);
392	          list.push({ p, r, c: (rand() * 5) | 0 });
393	        }
394	      }
395	    }
396	    build(list, group, sa - 6, sb + 6);
397	  }
398	
