406	  const nClusters = Math.round(26 * density);
407	  for (let k = 0; k < nClusters; k++) {
408	    const th0 = rand() * Math.PI * 2;
409	    const n = 10 + ((rand() * 16) | 0);
410	    for (let i = 0; i < n; i++) {
411	      const th = th0 + (rand() - 0.5) * 0.35;
412	      const r = b.rimRadius - 0.7 + (rand() - 0.4) * 1.3;
413	      const sz = 0.18 + rand() * 0.42;
414	      wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.35 + rand() * 0.55, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
415	    }
416	  }
417	  const nRim = Math.round(200 * density);
418	  for (let i = 0; i < nRim; i++) {
419	    const th = rand() * Math.PI * 2;
420	    const r = b.rimRadius - 0.4 + (rand() - 0.5) * 0.6;
421	    const sz = 0.1 + rand() * 0.18;
422	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
423	  }
424	  // along 3 spiral flow lines (constant th - C ln r) to echo the white foam bands
425	  const nBand = Math.round(60 * density);
426	  for (let i = 0; i < nBand; i++) {
427	    const band = ((i % 3) * Math.PI * 2) / 3 + 0.4;
428	    const r = 3.0 + rand() * (b.rimRadius - 3.6);
429	    const th = band + SPIRAL_C * Math.log(r) + (rand() - 0.5) * 0.12;
430	    const sz = 0.07 + rand() * 0.13;
431	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, c: (rand() * 5) | 0 });
432	  }
433	  const whirlStart = chunks.length;
434	  build(wl, whirlGroup, st03.s0 - 30, st04.s0 + 25);
435	  group.add(whirlGroup);
436	
437	  return {
438	    group,
439	    whirlGroup,
440	    berm: berm.mesh,
441	    instanceCount: total,
442	    update(time, focusS, outro = 0) {
443	      berm.uniforms.uTime.value = time;
444	      (berm.uniforms.uOutro.value as THREE.Vector2).x = outro;
445	      const s08 = course.stage('08').s0;
446	      for (let i = 0; i < chunks.length; i++) {
447	        const c = chunks[i];
448	        c.mesh.visible = c.sb > focusS - 25 && c.sa < focusS + 140 && !(outro > 0.3 && c.sb > s08 + 8);
449	      }
450	      // rotate whirlpool foam about the basin axis with the swirl (θ decreasing = course direction)
451	      whirlGroup.rotation.y = -time * 0.45 * ((Math.PI * 2) / 3);
452	      void whirlStart;
453	    },
454	  };
455	}
